```jsx
// src/components/Cart.js
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addProduct, removeProduct } from '../features/cart/cartSlice';

export default function Cart() {
  const items = useSelector((state) => state.cart.items);
  const dispatch = useDispatch();

  const total =
    items.reduce((acc, item) => acc + item.price * item.quantity, 0) || 0;

  return (
    <div className="cart">
      <h2>Shopping Cart</h2>
      <ul>
        {items.map((item) => (
          <CartItem
            key={item.id}
            item={item}
            onRemove={() => dispatch(removeProduct(item.id))}
          />
        ))}
      </ul>

      <p>Total: ${total.toFixed(2)}</p>
    </div>
  );

  function CartItem({ item, onRemove }) {
    return (
      <li>
        <h3>{item.name}</h3>
        <p>Quantity: {item.quantity}</p>

        <button onClick={onRemove}>
          Remove from cart
        </button>
      </li>
    );
  }
}
```

This is the simplest possible implementation — you'll need to add quantity buttons, error handling for when the user tries to remove something that's not in the cart, and whatever other features make sense for your app.

