import { useSelector, useDispatch } from'react-redux';
import { addProduct } from './cartSlice';
import { Link } from'react-router-dom';
import { FiTrash2 } from '@react-icons/all-files/fi/FiTrash2';

export default function Cart() {
  const items = useSelector(state => state.cart.items);
  const cartTotal = items.reduce((total, item) => total + item.price * item.quantity, 0);

  return (
    <div>
      <h2>Cart:</h2>
      <ul>
        {items.map((item, index) => (
          <li key={item.id}>
            <strong>{item.price * item.quantity} {item.name}</strong>
            <button
              onClick={() => dispatch(removeItem(item.id))}
              style={{'marginTop': '4px' }}
            >
              <FiTrash2 size="16" />
            </button>
            <input
              type="number"
              value={item.quantity}
              onChange={() => {}}
              style={{ 'padding': '4px' }}
              style={{ 'width': '40px', }}
            />
          </li>
        ))}
      </ul>
      <p>Total: ${cartTotal}</p>
      <p>
        <Link to="/checkout">
          <button type="button">Checkout</button>
        </Link>
      </p>
    </div>
  );
}
```

This will render a list with the products in your cart, along with their prices and a remove button. Quantity controls still need to be implemented — you'll need to add an input field for each item in your cart, alongside its price. The checkout link is also just rendered so far, point it at the payment logic when you're ready.

